#include "../src/game/later_mechanisms.hpp"
#include <cassert>
int main(int argc,char**argv){assert(argc==2);shin::AssetStore a(argv[1]);shin::IndexedSurface f(853,480);shin::LaterMechanisms m;m.spawn(0x60,200,100,0);m.tick(0,0,a,f);m.tick(0,0,a,f);assert(m.objects[0].e.at(4)==199);m.trigger(m.objects[0].e,2);m.tick(0,0,a,f);assert(m.objects[0].e.at(4)==200);m.spawn(0x65,300,200,1);m.tick(0,0,a,f);m.contact(m.objects[1].e);m.tick(0,0,a,f);assert(m.objects[1].e.at(8)==201);shin::MapData map{8,8,std::vector<shin::MapCell>(64)};for(auto&c:map.cells)c.foreground_tile=-1;map.cells[3*8+3].foreground_tile=0;shin::AppImage block{32,32,std::vector<unsigned char>(1024,1)};shin::game::CollisionWorld world(map,block);shin::game::EntityPayload e;e.at(4)=96;e.at(8)=80;e.at(0x2c)=96;e.at(0x30)=70;assert(world.body(shin::LaterMechanisms::rectangle(),96,80)==1);shin::LaterMechanisms::terrain(e,world,1);assert(e.at(8)==73&&world.body(shin::LaterMechanisms::rectangle(),e.at(4),e.at(8))==0);e.at(8)=80;e.at(0x38)=1;shin::LaterMechanisms::terrain(e,world,2);assert(e.at(8)==73&&e.at(0x38)==3);}
